        },
        async stop(workspaceId) {
          return API.post(`/api/workspaces/${workspaceId}/stop`, {})
        },
        async status(workspaceId) {
          return API.get(`/api/workspaces/${workspaceId}/status`)
        },
        async logs(workspaceId, tail = 200) {
